+    });
+  }
+
+  /**
+   * Get photos from the camera roll
+   */
+  static getPhotos(options) {
+    return new Promise((resolve, reject) => {
+      this.ifPlugin(() => {
+        window.CameraRoll.saveToCameraRoll(base64String);
+      })
+    });
